import{_ as e,C as i,c as r,o as n,j as t,G as a,b as u,a0 as l,a as s,w as h,a1 as d}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Handhabungsdruck","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/mental-strength/handling-pressure.md","filePath":"de/education/mental-strength/handling-pressure.md"}');const o=e({name:"de/education/mental-strength/handling-pressure.md"},[["render",function(e,c,o,g,k,m){const b=i("AdBanner"),f=i("Mermaid"),p=i("AdInArticle");return n(),r("div",null,[c[1]||(c[1]=t("h1",{id:"handhabungsdruck",tabindex:"-1"},[s("Handhabungsdruck "),t("a",{class:"header-anchor",href:"#handhabungsdruck","aria-label":'Permalink to "Handhabungsdruck"'},"​")],-1)),a(b),c[2]||(c[2]=t("p",null,"Druck gehört zum Wettbewerb dazu. Es geht nicht darum, ihn zu eliminieren – das ist unmöglich. Es geht darum, trotz des Drucks gute Leistungen zu erbringen und ihn sogar zu seinem Vorteil zu nutzen.",-1)),c[3]||(c[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"Die große Idee"),t("p",null,[t("strong",null,"Der Druck verschwindet nicht mit der Erfahrung – man lernt nur besser damit umzugehen."),s(" Die besten Spieler sind nicht ruhig; sie verstehen es, ihre Erregung produktiv zu nutzen.")])],-1)),(n(),u(d,null,{default:h(()=>[a(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDrucksituation%5D%20--%3E%20B%7BYour%20Response%7D%0A%20%20%20%20B%20--%3E%7CAnxiety%7C%20C%5BLeistungseinbr%C3%BCche%5D%0A%20%20%20%20B%20--%3E%7CExcitement%7C%20D%5BDie%20Leistung%20steigt%5D%0A%0A%20%20%20%20C%20--%3E%20E%5BNegative%20Gedanken%5D%0A%20%20%20%20C%20--%3E%20F%5BSpannung%5D%0A%20%20%20%20C%20--%3E%20G%5BSchwache%20Konzentration%5D%0A%0A%20%20%20%20D%20--%3E%20H%5BEnergetisiert%5D%0A%20%20%20%20D%20--%3E%20I%5BFokussiert%5D%0A%20%20%20%20D%20--%3E%20J%5BZuversichtlich%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A"})]),fallback:h(()=>[...c[0]||(c[0]=[s(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=l('<h2 id="druck-verstehen" tabindex="-1">Druck verstehen <a class="header-anchor" href="#druck-verstehen" aria-label="Permalink to &quot;Druck verstehen&quot;">​</a></h2><h3 id="wodurch-wird-druck-erzeugt" tabindex="-1">Wodurch wird Druck erzeugt? <a class="header-anchor" href="#wodurch-wird-druck-erzeugt" aria-label="Permalink to &quot;Wodurch wird Druck erzeugt?&quot;">​</a></h3><ul><li>Hoher Einsatz (wichtiges Spiel, entscheidender Wurf)</li><li>Beobachtet werden (Publikum, Teamkollegen)</li><li>Erwartungen (Ihre eigenen und die anderer)</li><li>Unsicherheit (knappes Ergebnis, unbekannte Gegner)</li><li>Zeit (läuft ab, wartet zu lange)</li></ul><h3 id="was-druck-mit-ihrem-korper-macht" tabindex="-1">Was Druck mit Ihrem Körper macht <a class="header-anchor" href="#was-druck-mit-ihrem-korper-macht" aria-label="Permalink to &quot;Was Druck mit Ihrem Körper macht&quot;">​</a></h3><p>Wenn Sie Druck verspüren, reagiert Ihr Körper:</p><ul><li>Herzfrequenz steigt</li><li>Die Atmung wird flach</li><li>Muskeln angespannt</li><li>Die Hände können zittern</li><li>Der Fokus verengt sich (manchmal zu sehr).</li></ul><p>Dein Körper bereitet sich auf eine Belastung vor. Das ist nichts Schlechtes – es ist Energie, die du nutzen kannst.</p><h2 id="umstrukturierungsdruck" tabindex="-1">Umstrukturierungsdruck <a class="header-anchor" href="#umstrukturierungsdruck" aria-label="Permalink to &quot;Umstrukturierungsdruck&quot;">​</a></h2><h3 id="druck-als-erregung" tabindex="-1">Druck als Erregung <a class="header-anchor" href="#druck-als-erregung" aria-label="Permalink to &quot;Druck als Erregung&quot;">​</a></h3><p>Die körperlichen Empfindungen von Angst und Aufregung sind nahezu identisch. Der Unterschied liegt in der Interpretation dieser Empfindungen.</p><p><strong>Interpretation der Angst:</strong> „Ich bin nervös, es könnte etwas Schlimmes passieren.“ <strong>Interpretation der Begeisterung:</strong> „Ich bin voller Energie, das ist mir wichtig.“</p><p><strong>Versuchen Sie Folgendes:</strong> Wenn Sie sich unter Druck gesetzt fühlen, sagen Sie zu sich selbst: „Ich bin aufgeregt“ anstatt „Ich bin nervös“.</p><h3 id="druck-als-privileg" tabindex="-1">Druck als Privileg <a class="header-anchor" href="#druck-als-privileg" aria-label="Permalink to &quot;Druck als Privileg&quot;">​</a></h3><p>Nur wichtige Momente erzeugen Druck. Wenn du ihn spürst, befindest du dich in einer Situation, die von Bedeutung ist.</p><blockquote><p>„Druck ist ein Privileg – er wird nur denen zuteil, die ihn sich verdienen.“ – Billie Jean King</p></blockquote><h2 id="techniken-fur-hochdruckmomente" tabindex="-1">Techniken für Hochdruckmomente <a class="header-anchor" href="#techniken-fur-hochdruckmomente" aria-label="Permalink to &quot;Techniken für Hochdruckmomente&quot;">​</a></h2><h3 id="_1-atemkontrolle" tabindex="-1">1. Atemkontrolle <a class="header-anchor" href="#_1-atemkontrolle" aria-label="Permalink to &quot;1. Atemkontrolle&quot;">​</a></h3><p>Dein Atem ist der schnellste Weg, deinen Zustand zu verändern.</p><p><strong>Die 4-7-8-Technik:</strong></p><ol><li>Vier Sekunden lang einatmen.</li><li>Halten Sie die Position für 7 Sekunden.</li><li>Atmen Sie 8 Sekunden lang aus.</li><li>2-3 Mal wiederholen</li></ol><p><strong>Schnellreset (im Kreis):</strong></p><ul><li>Ein langsamer, tiefer Atemzug</li><li>Spüre deine Füße auf dem Boden</li><li>Lassen Sie beim Ausatmen die Schultern sinken.</li></ul>',22)),a(p),c[5]||(c[5]=l('<h3 id="_2-physische-erdung" tabindex="-1">2. Physische Erdung <a class="header-anchor" href="#_2-physische-erdung" aria-label="Permalink to &quot;2. Physische Erdung&quot;">​</a></h3><p>Verbinde dich mit körperlichen Empfindungen, um aus deinen Gedanken herauszukommen:</p><ul><li>Spüre das Gewicht des Balles</li><li>Spüre deine Füße auf dem Boden</li><li>Drücken Sie Ihre Nicht-Wurfhand zusammen und lassen Sie sie wieder los.</li><li>Rollen Sie Ihre Schultern zurück</li></ul><h3 id="_3-fokusverengung" tabindex="-1">3. Fokusverengung <a class="header-anchor" href="#_3-fokusverengung" aria-label="Permalink to &quot;3. Fokusverengung&quot;">​</a></h3><p>In Drucksituationen sollten Sie sich nur auf das Wesentliche konzentrieren:</p><ul><li>Nicht das Ergebnis</li><li>Nicht das Publikum</li><li>Nicht das, was passieren könnte</li><li>Nur dieser Wurf, dieses Ziel, dieser Moment</li></ul><p><strong>Schlüsselworte:</strong> „Hier. Jetzt. Dies.“</p><h3 id="_4-prozessorientierung" tabindex="-1">4. Prozessorientierung <a class="header-anchor" href="#_4-prozessorientierung" aria-label="Permalink to &quot;4. Prozessorientierung&quot;">​</a></h3><p>Verlagerung vom Ergebnis zum Prozess:</p><p><strong>Ergebnisorientierung (erzeugt Druck):</strong></p><ul><li>&quot;Ich muss das machen.&quot;</li><li>„Wenn ich verfehle, verlieren wir.“</li><li>&quot;Alle schauen zu.&quot;</li></ul><p><strong>Prozessfokus (reduziert Druck):</strong></p><ul><li>&quot;Folge meiner Routine&quot;</li><li>&quot;Ziel im Auge behalten&quot;</li><li>&quot;Vertraue meinem Training&quot;</li></ul><h3 id="_5-der-linkshander-griff" tabindex="-1">5. Der Linkshänder-Griff <a class="header-anchor" href="#_5-der-linkshander-griff" aria-label="Permalink to &quot;5. Der Linkshänder-Griff&quot;">​</a></h3><p>Für Rechtshänder: Drücken Sie Ihre linke Hand 10-15 Sekunden lang zusammen.</p><ul><li>Aktiviert die rechte Gehirnhälfte</li><li>Beruhigt analytisches Grübeln</li><li>Hilft beim Zugriff auf die automatische Ausführung</li></ul><p>Nutze dies, wenn du merkst, dass du zu viel nachdenkst.</p><h2 id="vorbereitung-auf-den-druck" tabindex="-1">Vorbereitung auf den Druck <a class="header-anchor" href="#vorbereitung-auf-den-druck" aria-label="Permalink to &quot;Vorbereitung auf den Druck&quot;">​</a></h2><h3 id="druck-in-der-praxis-simulieren" tabindex="-1">Druck in der Praxis simulieren <a class="header-anchor" href="#druck-in-der-praxis-simulieren" aria-label="Permalink to &quot;Druck in der Praxis simulieren&quot;">​</a></h3><p>Man kann dem Druck im Wettkampf nicht standhalten, wenn man ihn im Training nie erlebt hat.</p><p><strong>Möglichkeiten, um Übungsdruck zu erzeugen:</strong></p><ul><li>Konsequenzen festlegen (Liegestütze bei Fehlern, Kaffee für den Partner/die Partnerin ausgeben)</li><li>Erstellen Sie „unbedingt umsetzbare“ Szenarien</li><li>Üben Sie vor Publikum</li><li>Zeitdruck (Schussuhr)</li><li>Ermüdung (Üben im müden Zustand)</li></ul><h3 id="visualisierung" tabindex="-1">Visualisierung <a class="header-anchor" href="#visualisierung" aria-label="Permalink to &quot;Visualisierung&quot;">​</a></h3><p>Stresssituationen mental durchspielen:</p><ol><li>Schließe deine Augen</li><li>Stellen Sie sich ein Druckszenario im Detail vor</li><li>Spüre die Druckempfindungen</li><li>Sieh dich selbst dabei, wie du gut damit umgehst</li><li>In Gedanken erfolgreich ausführen</li></ol><p>Tun Sie dies regelmäßig, nicht nur vor Wettkämpfen.</p><h3 id="aufbau-einer-druckgeschichte" tabindex="-1">Aufbau einer Druckgeschichte <a class="header-anchor" href="#aufbau-einer-druckgeschichte" aria-label="Permalink to &quot;Aufbau einer Druckgeschichte&quot;">​</a></h3><p>Notieren Sie sich Situationen, in denen Sie gut mit Druck umgegangen sind:</p><ul><li>Wie war die Situation?</li><li>Wie haben Sie sich gefühlt?</li><li>Was hast du gemacht?</li><li>Was war das Ergebnis?</li></ul><p>Lies dir das vor Wettkämpfen noch einmal durch, um dich daran zu erinnern: „Das habe ich schon einmal gemacht.“</p><h2 id="wahrend-des-wettbewerbs" tabindex="-1">Während des Wettbewerbs <a class="header-anchor" href="#wahrend-des-wettbewerbs" aria-label="Permalink to &quot;Während des Wettbewerbs&quot;">​</a></h2><h3 id="vor-dem-druckwurf" tabindex="-1">Vor dem Druckwurf <a class="header-anchor" href="#vor-dem-druckwurf" aria-label="Permalink to &quot;Vor dem Druckwurf&quot;">​</a></h3><ol><li>Treten Sie einen Schritt zurück, atmen Sie tief durch</li><li>Erinnere dich an deine Routine</li><li>Konzentriere dich auf den Prozess, nicht auf das Ergebnis.</li><li>Verwenden Sie Ihr Auslösewort oder Ihren Hinweis.</li></ol><h3 id="im-kreis" tabindex="-1">Im Kreis <a class="header-anchor" href="#im-kreis" aria-label="Permalink to &quot;Im Kreis&quot;">​</a></h3><ol><li>Führen Sie Ihr Übungsprogramm genau wie geübt durch.</li><li>Fokus nach außen (Ziel, nicht Körper).</li><li>Vertraue deinem Training</li><li>Ohne Zögern freigeben</li></ol><h3 id="nach-dem-wurf" tabindex="-1">Nach dem Wurf <a class="header-anchor" href="#nach-dem-wurf" aria-label="Permalink to &quot;Nach dem Wurf&quot;">​</a></h3><ul><li>Akzeptiere das Ergebnis ohne Wertung.</li><li>Wenn gut: kurze Bestätigung, weiter geht&#39;s.</li><li>Bei Fehler: SOAS-Methode, für den nächsten Durchlauf zurücksetzen.</li></ul><h2 id="haufige-fehler-bei-der-druckbeaufschlagung" tabindex="-1">Häufige Fehler bei der Druckbeaufschlagung <a class="header-anchor" href="#haufige-fehler-bei-der-druckbeaufschlagung" aria-label="Permalink to &quot;Häufige Fehler bei der Druckbeaufschlagung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fehler</th><th>Besserer Ansatz</th></tr></thead><tbody><tr><td>Eile</td><td>Langsamer vorgehen, die volle Routine nutzen</td></tr><tr><td>Überdenken</td><td>Externer Fokus, Vertrauenstraining</td></tr><tr><td>Technikwechsel</td><td>Bleib bei dem, was du kennst.</td></tr><tr><td>Fokus auf das Ergebnis</td><td>Fokus auf den Prozess</td></tr><tr><td>Nerven bekämpfen</td><td>Nimm die Energie an und nutze sie.</td></tr></tbody></table><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Der Druck verschwindet nicht mit der Erfahrung. Man lernt nur, besser damit umzugehen.</p></blockquote><p>Die besten Spieler sind nicht ruhig – sie verstehen es, ihre Erregung produktiv einzusetzen.</p>',42)),a(b)])}]]);export{c as __pageData,o as default};
